DO $patch$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.submit_candidacy(uuid,uuid)'::regprocedure) INTO def; def:=replace(def,$old$SELECT COALESCE(engagement,0) INTO engagement FROM public.civic_stats WHERE character_id=cid$old$,$new$SELECT COALESCE(cs.engagement,0) INTO engagement FROM public.civic_stats cs WHERE character_id=cid$new$); EXECUTE def; SELECT pg_get_functiondef('public.start_campaign_action(uuid,text,jsonb)'::regprocedure) INTO def; def:=replace(def,$old$r.id<>'debate' AND ca.character_id IS DISTINCT FROM cid$old$,$new$r.id NOT IN('terrain','tractage','rencontre') AND ca.character_id IS DISTINCT FROM cid$new$); EXECUTE def;
SELECT pg_get_functiondef('public.refresh_election(uuid)'::regprocedure) INTO def; def:=replace(def,$old$FOR ca IN SELECT * FROM public.candidacies WHERE election_id=e.id AND character_id IS NOT NULL AND status='validated' ORDER BY character_id LOOP PERFORM public.award_political(ca.character_id,'election:'||e.id,'election',CASE WHEN ca.id=winner THEN 8 ELSE 2 END,CASE WHEN ca.id=winner THEN 5 ELSE 1 END,0,0,'Résultat municipal'); END LOOP;$old$,''); EXECUTE def;
SELECT pg_get_functiondef('public.election_state()'::regprocedure) INTO def; def:=replace(def,$old$END LOOP; RETURN jsonb_build_object$old$,$new$END LOOP; PERFORM public.award_political(cid,'election:'||a.election_id,'election',CASE WHEN e.winner_id=a.id THEN 8 ELSE 2 END,CASE WHEN e.winner_id=a.id THEN 5 ELSE 1 END,0,0,'Résultat municipal') FROM public.candidacies a JOIN public.elections e ON e.id=a.election_id WHERE a.character_id=cid AND a.status='completed' AND e.status='completed'; RETURN jsonb_build_object$new$); EXECUTE def; END $patch$;